llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Isotretinoin, a retinoid sharing the same cyclohexenyl-polyene scaffold as the query, has a systemic bioavailability of 40% in patients, directly demonstrating that this lipophilic retinoid class can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "In healthy subjects, cis-lycopene, a highly lipophilic long-chain polyene, showed 24.5% bioavailability, supporting that even very lipophilic conjugated molecules can achieve F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Desvenlafaxine, which contains a p-hydroxyphenyl group like the query, has 80.5% absolute oral bioavailability, showing the phenolic moiety is not a barrier to high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Teriflunomide, an amide-containing drug with an aryl group, has absolute oral bioavailability approaching 100%, supporting high absorption for amide/aryl structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A tomato-paste lycopene study reported only 0.17% systemic availability, but this food-matrix-specific carotenoid result has very low transferability (0.0115) to the drug-like query and is outweighed by high-transfer retinoid evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer experimental evidence from retinoid and lipophilic polyene analogues (isotretinoin 40%, cis-lycopene 24.5%) and from phenol/amide-containing drugs (desvenlafaxine 80.5%, teriflunomide ~100%) supports F ≥20%. Low-transfer lycopene food-matrix data showing low systemic availability are not transferable to the drug-like query. The physicochemical prior of poor solubility is a concern but is overridden by direct analogue evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability value for fenretinide in humans; no IV comparator data.",
    "Extent of first-pass metabolism, especially phenol glucuronidation/sulfation, is not directly assessed.",
    "Formulation and food effects on fenretinide absorption are not captured in the available evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

